import { getGlobalSettings } from "@/db/models/GlobalSettings";
import { getHoldings } from "@/db/positionLedger";
import { markHoldings } from "@/db/pumpFunApi";
import { resolveTraderSettings } from "@/db/settings";

/**
 * Plain-object trader with `muted` resolved against the global default, and
 * a lightweight `sim` summary - cached counters only (balance, realized
 * PnL, position counts), no live price lookups. Cheap enough to include on
 * every trader in a list poll.
 */
export async function resolveTraderView(traderDoc, globalSettings) {
  const settings = globalSettings || (await getGlobalSettings());
  const plain = JSON.parse(JSON.stringify(traderDoc));
  return {
    ...plain,
    id: plain._id,
    mutedOverride: plain.muted,
    muted: plain.muted === null || plain.muted === undefined ? settings.defaultMuted : plain.muted,
  };
}

export async function resolveTraderViews(traderDocs) {
  const settings = await getGlobalSettings();
  return Promise.all(traderDocs.map((t) => resolveTraderView(t, settings)));
}

/**
 * Full detail view: trader + resolved effective simulation settings (so
 * the UI can show "inherited: $20" vs an explicit override) + current
 * mark-to-market holdings (live pump.fun price lookup - only ever call this
 * for a single-trader detail view, never a list).
 */
export async function resolveTraderViewWithHoldings(traderDoc) {
  const [view, holdings, effectiveSettings] = await Promise.all([
    resolveTraderView(traderDoc),
    getHoldings(traderDoc.address),
    resolveTraderSettings(traderDoc),
  ]);
  const markedHoldings = await markHoldings(holdings);
  const holdingsValueUsd = markedHoldings.reduce((sum, h) => sum + (h.currentValueUsd || 0), 0);
  return { ...view, holdings: markedHoldings, holdingsValueUsd, effectiveSettings };
}
